// --- Configuration --- 
const SEGMENT_CODE_COLUMN = 'SegmentCode';
const SEGMENT_TITLE_COLUMN = 'SegmentTitle';

const FAMILY_CODE_COLUMN = 'FamilyCode';
const FAMILY_TITLE_COLUMN = 'FamilyTitle';

const CLASS_CODE_COLUMN = 'ClassCode';
const CLASS_TITLE_COLUMN = 'ClassTitle';

const BRICK_CODE_COLUMN = 'BrickCode';
const BRICK_TITLE_COLUMN = 'BrickTitle';

// --- Helper Function --- 
function safeGet(item, key, defaultValue = '') {
  return item && item[key] !== undefined && item[key] !== null ? String(item[key]).trim() : defaultValue;
}

// --- Main Logic --- 
const inputRows = items.map(item => item.json);

const gpcHierarchy = {}; // Segment > Family > Class > Brick 계층 구조 저장

// 1. GPC 계층 정보 파싱 및 구조화
for (const row of inputRows) {
  const segmentCode = safeGet(row, SEGMENT_CODE_COLUMN);
  const familyCode = safeGet(row, FAMILY_CODE_COLUMN);
  const classCode = safeGet(row, CLASS_CODE_COLUMN);
  const brickCode = safeGet(row, BRICK_CODE_COLUMN);

  // Segment 정보 저장
  if (segmentCode && !gpcHierarchy[segmentCode]) {
    gpcHierarchy[segmentCode] = {
      code: segmentCode,
      title: safeGet(row, SEGMENT_TITLE_COLUMN),
      families: {}
    };
  }

  // Family 정보 저장
  if (segmentCode && familyCode && gpcHierarchy[segmentCode] && !gpcHierarchy[segmentCode].families[familyCode]) {
    gpcHierarchy[segmentCode].families[familyCode] = {
      code: familyCode,
      title: safeGet(row, FAMILY_TITLE_COLUMN),
      classes: {}
    };
  }

  // Class 정보 저장
  if (segmentCode && familyCode && classCode && 
      gpcHierarchy[segmentCode] && gpcHierarchy[segmentCode].families[familyCode] && 
      !gpcHierarchy[segmentCode].families[familyCode].classes[classCode]) {
    gpcHierarchy[segmentCode].families[familyCode].classes[classCode] = {
      code: classCode,
      title: safeGet(row, CLASS_TITLE_COLUMN),
      bricks: {}
    };
  }

  // Brick 정보 저장
  if (segmentCode && familyCode && classCode && brickCode && 
      gpcHierarchy[segmentCode] && gpcHierarchy[segmentCode].families[familyCode] && 
      gpcHierarchy[segmentCode].families[familyCode].classes[classCode] && 
      !gpcHierarchy[segmentCode].families[familyCode].classes[classCode].bricks[brickCode]) {
    gpcHierarchy[segmentCode].families[familyCode].classes[classCode].bricks[brickCode] = {
      code: brickCode,
      title: safeGet(row, BRICK_TITLE_COLUMN),
      // 상위 계층 정보도 미리 저장
      classCode: classCode,
      familyCode: familyCode,
      segmentCode: segmentCode
    };
  }
}

// 2. "통합 검색용 텍스트 문서" 생성
const resultItems = [];

for (const segmentCode in gpcHierarchy) {
  const segment = gpcHierarchy[segmentCode];
  for (const familyCode in segment.families) {
    const family = segment.families[familyCode];
    for (const classCode in family.classes) {
      const classObj = family.classes[classCode];
      for (const brickCode in classObj.bricks) {
        const brick = classObj.bricks[brickCode];
        let integratedText = "";

        // 순서: Brick -> Class -> Family -> Segment (Title만 사용)
        if (brick.title) integratedText += `Brick: ${brick.title}; `;
        if (classObj.title) integratedText += `Class: ${classObj.title}; `;
        if (family.title) integratedText += `Family: ${family.title}; `;
        if (segment.title) integratedText += `Segment: ${segment.title}; `;

        if (integratedText.trim()) {
          resultItems.push({
            json: {
              brick_code: brick.code,
              brick_title: brick.title,
              class_code: classObj.code,
              class_title: classObj.title,
              family_code: family.code,
              family_title: family.title,
              segment_code: segment.code,
              segment_title: segment.title,
              // 임베딩될 최종 텍스트
              document_text: integratedText.trim().replace(/\s\s+/g, ' ')
            }
          });
        }
      }
    }
  }
}

// 최종 결과 반환
return resultItems;
